import java.util.UUID
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34])
class RemoteStorageRoomTest {
 private val context:Context=ApplicationProvider.getApplicationContext();private val handles=mutableListOf<CycleCareDatabase>();private val names=mutableListOf<String>()
 private fun open():CycleCareDatabase{val name="outbox-${UUID.randomUUID()}";names+=name;return Room.databaseBuilder(context,CycleCareDatabase::class.java,name).allowMainThreadQueries().build().also{handles+=it;RustEnrollmentStage.schema(it.openHelper.writableDatabase);RustEnrollmentStage.senderSchema(it.openHelper.writableDatabase);val sql=it.openHelper.writableDatabase;sql.execSQL("CREATE TABLE IF NOT EXISTS rust_float_bits(dateString TEXT NOT NULL PRIMARY KEY,normalizedHash TEXT NOT NULL,bbtBits INTEGER NOT NULL,sleepBits INTEGER NOT NULL)");for(event in listOf("INSERT","UPDATE","DELETE")){val ref=if(event=="INSERT")"NEW.dateString"else"OLD.dateString";sql.execSQL("CREATE TRIGGER IF NOT EXISTS remote_float_${event.lowercase()} AFTER $event ON cycle_day_logs BEGIN DELETE FROM rust_float_bits WHERE dateString=$ref; END")}}}
 @After fun close(){handles.forEach{it.close()};names.forEach{context.deleteDatabase(it)}}
 private fun entry(base:Long=7,attempts:Int=2)=HealthSyncOutboxEntry("owner","op","2026-10-01","UPSERT",base,17,"synthetic 🌸/\n",HealthSyncPayloadCodec.hash("synthetic 🌸/\n"),3,attempts,77,"OLD_ERROR","OLD_RECEIPT",45)
 private fun seed(db:CycleCareDatabase,e:HealthSyncOutboxEntry,server:Long=3,revision:Boolean=true){db.runInTransaction{val s=db.openHelper.writableDatabase;if(revision)s.execSQL("INSERT INTO health_sync_revisions(ownerId,recordId,revision,payloadHash,tombstone,updatedAt,serverRevision) VALUES(?,?,?,?,?,?,?)",arrayOf<Any>(e.ownerId,e.recordId,99,"KEEP_HASH",1,987,server));for(row in listOf(e,e.copy(operationId="sibling",revision=18),e.copy(operationId="different-base",baseRevision=e.baseRevision xor 1L),e.copy(operationId="other-record",recordId="2026-10-02"),e.copy(operationId="other-owner",ownerId="other"))){s.execSQL("INSERT INTO health_sync_outbox VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(row.ownerId,row.operationId,row.recordId,row.kind,row.baseRevision,row.revision,row.payloadJson,row.payloadHash,row.consentGeneration,row.attempts,row.nextAttemptAt,row.lastError,row.serverReceipt,row.serverRevision))}}}
 private fun snapshot(db:CycleCareDatabase):List<List<String?>>{val out=mutableListOf<List<String?>>();for(table in listOf("rust_float_bits","cycle_day_logs","onboarding_profiles","cycle_settings","health_sync_revisions","health_sync_outbox","health_sync_conflicts","health_sync_cursors")){out+=listOf(table);db.openHelper.writableDatabase.query("SELECT * FROM $table ORDER BY 1,2").use{c->while(c.moveToNext())out+=(0 until c.columnCount).map{if(c.isNull(it))null else c.getString(it)}}};return out}


 private fun apply(db:CycleCareDatabase,changes:List<RustRemoteRows.Change>,native:Boolean,now:Long=999):Int{var result=0;db.runInTransaction{val sql=db.openHelper.writableDatabase;result=if(native)RustRemoteStorage.apply(sql,"owner",changes,now)else RustRemoteRows.apply(sql,"owner",changes,now)};return result}
 private fun log(id:String="2026-10-01")=CycleDayLog(id,flowLevel="LIGHT",notes="synthetic 🌸/\n",bbtCelsius=Float.fromBits(Int.MIN_VALUE),sleepHours=Float.fromBits(1))
 private fun initial(db:CycleCareDatabase){db.runInTransaction{val sql=db.openHelper.writableDatabase;RustDomainRows.write(sql,"settings",RustDomainRows.Row.Settings(CycleSettings(isAppLockEnabled=true,lockTimeoutMinutes=19,lutealPhaseDays=17,isPregnancyMode=true,pregnancyDueDate="KEEP",remindDailyLog=true)));RustDomainRows.write(sql,"profile",RustDomainRows.Row.Profile(OnboardingProfile(completedAtTimestamp=44,lastPeriodEndDateString="KEEP_END",typicalEnergy="KEEP_ENERGY",hasCompletedDeepBaseline=true)));RustDomainRows.write(sql,"2026-10-01",RustDomainRows.Row.Log(log()))}}
 @Test fun fullDatabaseExactOriginalMixedRepeatedKeysStaleConflictMergeAndTombstones(){
  RustTrackNative.warmUp();for(tombstone in listOf(false,true))for(pending in listOf(false,true))for(local in listOf(Long.MIN_VALUE,0L,Long.MAX_VALUE-1)){
   val a=open();val b=open();for(db in listOf(a,b)){initial(db);val sql=db.openHelper.writableDatabase;sql.execSQL("INSERT INTO health_sync_revisions VALUES('owner','2026-10-01',?,'old',0,1,1)",arrayOf(local));if(pending)seed(db,entry().copy(revision=23),revision=false)}
   val changes=listOf(RustRemoteRows.Change("2026-10-01",2,1,if(tombstone)null else HealthSyncPayloadCodec.logPayload(log()),tombstone),RustRemoteRows.Change("settings",2,2,if(tombstone)null else HealthSyncPayloadCodec.settingsPayload(CycleSettings(averageCycleLength=33)),tombstone),RustRemoteRows.Change("profile",2,3,if(tombstone)null else HealthSyncPayloadCodec.profilePayload(OnboardingProfile(completedAtTimestamp=55,selectedGoalsCsv="remote")),tombstone),RustRemoteRows.Change("settings",1,4,"INVALID_PAYLOAD_SKIPPED",false),RustRemoteRows.Change("2026-10-02",1,5,HealthSyncPayloadCodec.logPayload(log("2026-10-02")),false))
   assertEquals(apply(a,changes,false),apply(b,changes,true));assertEquals(snapshot(a),snapshot(b));val settings=(RustDomainRows.read(b.openHelper.writableDatabase,"settings")as RustDomainRows.Row.Settings).value;assertEquals(19,settings.lockTimeoutMinutes);assertTrue(settings.isAppLockEnabled);val before=snapshot(b);assertTrue(runCatching{apply(b,changes,true)}.exceptionOrNull()is IllegalArgumentException);assertEquals(before,snapshot(b))
  }
 }
 @Test fun emptyHundredAndRepeatedSameRecordPagesMatchOriginal(){RustTrackNative.warmUp();for(size in listOf(0,1,100)){val a=open();val b=open();initial(a);initial(b);val changes=List(size){i->RustRemoteRows.Change("settings",i+1L,i+1L,HealthSyncPayloadCodec.settingsPayload(CycleSettings(averageCycleLength=20+i%10)),false)};assertEquals(size,apply(a,changes,false));assertEquals(size,apply(b,changes,true));assertEquals(snapshot(a),snapshot(b))}}
 @Test fun lateInvalidPayloadSequenceDateTombstoneAndOverflowRollbackWholePage(){
  RustTrackNative.warmUp();for(native in listOf(false,true))for(kind in listOf("sequence","date","tombstone","payload","overflow")){val db=open();initial(db);val sql=db.openHelper.writableDatabase;if(kind=="overflow")sql.execSQL("INSERT INTO health_sync_revisions VALUES('owner','2026-10-02',?,'old',0,1,0)",arrayOf(Long.MAX_VALUE));val before=snapshot(db);val first=RustRemoteRows.Change("settings",1,1,HealthSyncPayloadCodec.settingsPayload(CycleSettings()),false);val second=when(kind){"sequence"->RustRemoteRows.Change("2026-10-02",1,1,null,true);"date"->RustRemoteRows.Change("2026-1-02",1,2,null,true);"tombstone"->RustRemoteRows.Change("2026-10-02",1,2,"not_null",true);"payload"->RustRemoteRows.Change("2026-10-02",1,2,"invalid",false);else->RustRemoteRows.Change("2026-10-02",1,2,HealthSyncPayloadCodec.logPayload(log("2026-10-02")),false)};assertNotNull(runCatching{apply(db,listOf(first,second),native)}.exceptionOrNull());assertEquals(before,snapshot(db))}
  val db=open();val before=snapshot(db);for(native in listOf(false,true)){assertTrue(runCatching{apply(db,emptyList(),native,now=-1)}.exceptionOrNull()is IllegalArgumentException);assertTrue(runCatching{apply(db,List(101){RustRemoteRows.Change("settings",1,it+1L,null,true)},native)}.exceptionOrNull()is IllegalArgumentException);assertEquals(before,snapshot(db))}
 }
 @Test fun allDomainRevisionConflictAndCursorBeforeAfterFaultsRollbackAndRetry(){
  RustTrackNative.warmUp();for(timing in listOf("BEFORE","AFTER"))for(point in listOf("domain","bits","revision","cursor","conflict")){val db=open();initial(db);if(point=="conflict")seed(db,entry(),revision=false);val sql=db.openHelper.writableDatabase;val before=snapshot(db);val clause=when(point){"domain"->"UPDATE ON cycle_day_logs";"bits"->"INSERT ON rust_float_bits";"revision"->"INSERT ON health_sync_revisions";"conflict"->"INSERT ON health_sync_conflicts";else->"INSERT ON health_sync_cursors"};sql.execSQL("CREATE TRIGGER fault $timing $clause BEGIN SELECT RAISE(ABORT,'remote fault'); END");val changes=listOf(RustRemoteRows.Change("2026-10-01",2,1,HealthSyncPayloadCodec.logPayload(log()),false));assertNotNull(runCatching{apply(db,changes,true)}.exceptionOrNull());assertEquals(before,snapshot(db));sql.execSQL("DROP TRIGGER fault");assertEquals(if(point=="conflict")0 else 1,apply(db,changes,true))}
 }
 @Test fun actualHostSameDatabaseOriginalControlAndConsentIdentityRefusals()=runBlocking{
  RustTrackNative.warmUp();val db=open();initial(db);val changes=listOf(RustRemoteRows.Change("settings",1,1,HealthSyncPayloadCodec.settingsPayload(CycleSettings(averageCycleLength=31)),false));val prefs=AuthPreferences(context,context.getSharedPreferences("remote-${UUID.randomUUID()}",Context.MODE_PRIVATE),true).apply{userId="owner";isCloudSyncAllowed=true;check(saveServerHealthConsentReceipt("owner",sessionGeneration,healthConsentGeneration,31,true))};val h=RustBoundRoomHost(prefs);val t=(h.publish(null,db,prefs.rustOperationSnapshot())as RustBoundRoomHost.Result.Value).value;val before=snapshot(db);var expected:List<List<String?>>?=null;val control=runCatching{db.runInTransaction{RustRemoteRows.apply(db.openHelper.writableDatabase,"owner",changes,999);expected=snapshot(db);throw IllegalStateException("original rollback")}}.exceptionOrNull();assertEquals("original rollback",control?.message);assertEquals(before,snapshot(db))
  suspend fun call(server:Long=31)=withContext(Dispatchers.IO){h.applyRemotePage(t,server,changes,999)}
  assertEquals(RustBoundRoomHost.Result.Stale,call(32));assertEquals(before,snapshot(db));assertEquals(1,(call()as RustBoundRoomHost.Result.Value).value);assertEquals(expected,snapshot(db));prefs.markPendingHealthSyncRevoke();assertEquals(RustBoundRoomHost.Result.Stale,call());assertEquals(expected,snapshot(db));prefs.userId="other";assertEquals(RustBoundRoomHost.Result.Stale,call());assertEquals(expected,snapshot(db))
 }
 @Test fun privateSessionRejectsWrongIndexSequenceNextReentryThreadAndClosed(){
  RustTrackNative.warmUp();val db=open();initial(db);val sql=db.openHelper.writableDatabase;val changes=listOf(RustRemoteRows.Change("2026-10-02",1,1,HealthSyncPayloadCodec.logPayload(log("2026-10-02")),false));val before=snapshot(db);val field=RustRemoteStorage::class.java.getDeclaredField("entered").apply{isAccessible=true};@Suppress("UNCHECKED_CAST")val entered=field.get(RustRemoteStorage)as ThreadLocal<Boolean>;val cls=Class.forName("com.cyclecare.app.data.local.rust.RustRemoteStorage\$Session");val ctor=cls.declaredConstructors.single().apply{isAccessible=true}
  fun call(session:Any,name:String,vararg args:Any):Any?{val m=cls.declaredMethods.single{it.name==name}.apply{isAccessible=true};return try{m.invoke(session,*args)}catch(e:java.lang.reflect.InvocationTargetException){throw e.cause!!}}
  val end=runCatching{db.runInTransaction{entered.set(true);val session=ctor.newInstance(sql,"owner",changes,999L);try{assertNotNull(runCatching{call(session,"remote",0)}.exceptionOrNull());assertNotNull(runCatching{RustRemoteStorage.apply(sql,"owner",changes,999)}.exceptionOrNull());val error=java.util.concurrent.atomic.AtomicReference<Throwable>();val thread=Thread{try{call(session,"ready")}catch(e:Throwable){error.set(e)}};thread.start();thread.join(5000);assertFalse(thread.isAlive);assertTrue(error.get()is IllegalStateException);assertEquals(1,call(session,"ready"));assertEquals(0L,call(session,"cursor"));assertNotNull(runCatching{call(session,"remote",1)}.exceptionOrNull());assertEquals(1L,call(session,"remote",0));assertEquals(1L,call(session,"sequence",0));call(session,"inspect",0);assertEquals(0L,call(session,"server",0));assertEquals(false,call(session,"pending",0));call(session,"prepare",0);assertEquals(0L,call(session,"local",0));call(session,"domain",0);assertNotNull(runCatching{call(session,"revision",0,2L)}.exceptionOrNull());call(session,"revision",0,1L);assertNotNull(runCatching{call(session,"advance",0,2L)}.exceptionOrNull());call(session,"advance",0,1L);assertNotNull(runCatching{call(session,"outcome",0)}.exceptionOrNull());assertEquals(1,call(session,"outcome",1));call(session,"close");assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());throw IllegalStateException("adversarial rollback")}finally{call(session,"close");entered.remove()}}}.exceptionOrNull();assertEquals("adversarial rollback",end?.message);assertEquals(before,snapshot(db))
 }

}
